def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    divisor = D(n)
    numerator = 20**(n + 1)

    # Handle the case where the divisor is 0, although D(n) is always positive for n >= 0
    if divisor == 0:
        return "N/A (Divisor is zero)"

    is_divisible = (numerator % divisor == 0)
    return is_divisible

results = {}
for n in range(11):
    is_div = check_divisibility(n)
    results[n] = {
        "D(n)": D(n),
        "Divisible": is_div
    }

print("Results for n=0 to n=10:")
for n, data in results.items():
    print(f"n={n}: D(n)={data['D(n)']}, Divides 20^{n+1}? {data['Divisible']}")

def is_5_smooth(k):
    """Checks if k is composed only of prime factors 2 and 5."""
    if k <= 0:
        return False

    # Repeatedly divide by 2 and 5
    while k % 2 == 0:
        k //= 2
    while k % 5 == 0:
        k //= 5

    # If the remaining number is 1, it was 5-smooth
    return k == 1

# We need to check n from 0 to 40.
# F(n) = (n+1)^2 + 1
n_values = range(41)
solutions = []

for n in n_values:
    F_n = (n + 1)**2 + 1
    if is_5_smooth(F_n):
        solutions.append(n)

print(solutions)

def get_prime_factors(k):
    factors = {}
    d = 2
    temp = k
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def is_2_5_smooth(k):
    if k == 1:
        return True
    factors = get_prime_factors(k)
    for p in factors:
        if p not in [2, 5]:
            return False
    return True

# We need to check up to n=40
solutions = []
results_list = []

for n in range(41):
    # D(n) = n^3 + 4n^2 + 6n + 4
    D_n = n**3 + 4*n**2 + 6*n + 4

    if is_2_5_smooth(D_n):
        solutions.append(n)

    # Get factorization for logging
    factors = get_prime_factors(D_n)
    factor_str = "".join(f"{p}^{e}" for p, e in sorted(factors.items()))

    results_list.append((n, D_n, factor_str, is_2_5_smooth(D_n)))

# Print results for analysis and note writing
print("N, D(N), Factorization, Is_Smooth")
for n, D_n, factor_str, is_smooth in results_list:
    print(f"{n}, {D_n}, {factor_str}, {is_smooth}")

print("\nSolutions found up to n=40:", solutions)
